private setMoreMenuVisible(visible: boolean): void {
    if (visible && (!this.inputEnabled || this.controlObscured || this.frame().visibility <= 0))
        return;
    if (this.moreMenuVisible === visible)
        return;
    if (visible) {
        this.moreMenuMeasuredWidth = 0;
        this.moreMenuEpoch++;
    }
    this.moreMenuVisible = visible;
    this.onTemporaryLayerChange(visible);
}

private dismissMoreMenuForEpoch(epoch: number): void {
    if (!this.moreMenuVisible || epoch !== this.moreMenuEpoch)
        return;
    this.dismissMoreMenu();
}

private performMoreAction(action: 'info' | 'refresh' | 'download'): void {
    if (!this.moreMenuVisible || !this.inputEnabled || this.controlObscured)
        return;
    if (action === 'refresh' && !this.chapterRefreshEnabled)
        return;
    if (action === 'download' && !this.bookDownloadEnabled)
        return;
    this.dismissMoreMenu();
    if (action === 'info')
        this.onOpenBookInfo();
    else if (action === 'refresh')
        this.onRefreshChapter();
    else
        this.onDownloadBook();
}

private performMoreActionForEpoch(epoch: number, action: 'info' | 'refresh' | 'download'): void {
    if (!this.moreMenuVisible || epoch !== this.moreMenuEpoch)
        return;
    this.performMoreAction(action);
}

private readerMoreSurfaceSpec(): PopupSurfaceSpec {
    return resolvePopupSpec('reader-more-menu');
}

private readerMoreActionEnabled(action: 'info' | 'refresh' | 'download'): boolean {
    return this.inputEnabled && !this.controlObscured &&
        (action !== 'refresh' || this.chapterRefreshEnabled) &&
        (action !== 'download' || this.bookDownloadEnabled);
}

private readerMoreActions(): ReaderMenuActionView[] {
    return [
        new ReaderMenuActionView('info', '书籍信息', this.readerMoreActionEnabled('info')),
        new ReaderMenuActionView('refresh', '刷新本章', this.readerMoreActionEnabled('refresh')),
        new ReaderMenuActionView('download', this.bookDownloadActive ? '正在下载章节…' : '下载全部章节', this.readerMoreActionEnabled('download')),
    ];
}

private readerMoreSheetHeight(): number {
    const metrics = ReaderWindowCoordinator.metrics();
    const available = this.layout.viewportHeight > 0 ? this.layout.viewportHeight : metrics.windowRect.height;
    const safeBottom = readerInteractiveSafeBottom(metrics);
    const maximum = Math.max(1, Math.min(available - safeBottom, Math.round((available - safeBottom) * 0.78)));
    const rows = this.readerMoreSurfaceSpec().actionHeight * this.readerMoreActions().length;
    const natural = MANGA_SHEET.handleZone + MANGA_SHEET.closeSize + MANGA_SHEET.quickHeaderPaddingBottom +
        rows + MANGA_SHEET.quickPaddingBottom + safeBottom;
    return Math.max(1, Math.min(maximum, natural));
}

private readerMoreSheetBodyHeight(): number {
    const rows = this.readerMoreSurfaceSpec().actionHeight * this.readerMoreActions().length;
    const usable = this.readerMoreSheetHeight() - readerInteractiveSafeBottom(ReaderWindowCoordinator.metrics()) -
        MANGA_SHEET.handleZone - MANGA_SHEET.closeSize - MANGA_SHEET.quickHeaderPaddingBottom - MANGA_SHEET.quickPaddingBottom;
    return Math.max(1, Math.min(rows, usable));
}

private readerMoreSheetOptions(): SheetOptions {
    const height = this.readerMoreSheetHeight();
    const epoch = this.moreMenuEpoch;
    return {
        height,
        width: '100%',
        preferType: SheetType.BOTTOM,
        dragBar: false,
        showClose: false,
        backgroundColor: mangaDirectoryColor('surface', this.appScheme),
        radius: { topLeft: MANGA_SHEET.quickSheetRadius, topRight: MANGA_SHEET.quickSheetRadius, bottomLeft: 0, bottomRight: 0 },
        maskColor: mangaDirectoryColor('scrim', this.appScheme),
        enableOutsideInteractive: false,
        onDisappear: (): void => this.dismissMoreMenuForEpoch(epoch),
    };
}

