@Builder
private boundaryLoadingPlaceholder() {
    .width<
    >('100%').height<
    >('100%').justifyContent<
    >(FlexAlign.Center)
        .backgroundColor<
    >(this.paperColor()).hitTestBehavior<
    >(HitTestMode.Block);
}

private paperColor(): string {
    return this.backgroundPreference === 'ink' ? '#1C1E1A' : this.backgroundPreference === 'white' ? '#FFFFFF' : '#F8F4EC';
}

build() {
    .width<
    >('100%').height<
    >('100%').backgroundColor<
    >(this.paperColor())
        .expandSafeArea<
    >([SafeAreaType.SYSTEM, SafeAreaType.CUTOUT], [SafeAreaEdge.TOP, SafeAreaEdge.BOTTOM, SafeAreaEdge.START, SafeAreaEdge.END])
        .ignoreLayoutSafeArea<
    >([LayoutSafeAreaType.SYSTEM], [LayoutSafeAreaEdge.ALL]);
}

private dismissMoreMenu(): void {
    this.moreMenuVisible = false;
    this.moreSelectionId = '';
}

private dismissMoreMenuForSelection(selectionId: string): void {
    if (!this.mounted || !this.moreMenuVisible || selectionId.length === 0 || selectionId !== this.moreSelectionId)
        return;
    this.dismissMoreMenu();
}

private moreIntentAction(identity: string, action: () => void): () => void {
    return (): void => {
        if (!this.mounted || !this.moreMenuVisible || identity.length === 0 || identity !== this.moreSelectionId)
            return;
        action();
    };
}

@Builder
private shellContent() {
        .width<
    >('100%')
        .height<
    >('100%')
        .onAreaChange<
    >((_oldValue: Area, newValue: Area): void => {
        const width = this.numericAreaLength(newValue.width);
        if (width > 0 && Math.abs(width - this.viewportWidth) >= 0.01) {
            this.viewportWidth = width;
        }
        const height = this.numericAreaLength(newValue.height);
        if (height > 0 && Math.abs(height - this.viewportHeight) >= 0.01)
            this.viewportHeight = height;
        this.overlayOriginX = Number(newValue.globalPosition.x);
        this.overlayOriginY = Number(newValue.globalPosition.y);
    })
        .bindSheet<
    >(this.moreMenuVisible, this.bookshelfMoreSheetBuilder(this.moreSelectionId), this.bookshelfMoreSheetOptions());
}

private bookshelfMoreSheetBuilder(selectionId: string): CustomBuilder {
    return (): void => this.bookshelfMoreSheet(selectionId);
}

private bookshelfMoreSheetOptions(): SheetOptions {
    const selectionId = this.moreSelectionId;
    return { height: this.bookshelfMoreSheetHeight(), width: '100%', preferType: SheetType.BOTTOM, dragBar: false, showClose: false,
        backgroundColor: mangaDirectoryColor('surface', this.appThemeScheme),
        radius: { topLeft: MANGA_SHEET.quickSheetRadius, topRight: MANGA_SHEET.quickSheetRadius, bottomLeft: 0, bottomRight: 0 },
        maskColor: mangaDirectoryColor('scrim', this.appThemeScheme), enableOutsideInteractive: false,
        onDisappear: (): void => this.dismissMoreMenuForSelection(selectionId) };
}

private bookshelfMoreSheetHeight(): number {
    const metrics = ReaderWindowCoordinator.metrics();
    const available = this.viewportHeight > 0 ? this.viewportHeight : metrics.windowRect.height;
    const safeBottom = readerInteractiveSafeBottom(metrics);
    const maximum = Math.max(1, Math.min(available - safeBottom, Math.round((available - safeBottom) * 0.78)));
    const rows = resolvePopupSpec('bookshelf-more-menu').actionHeight * 4;
    const natural = MANGA_SHEET.handleZone + MANGA_SHEET.closeSize + MANGA_SHEET.quickHeaderPaddingBottom +
        rows + MANGA_SHEET.quickPaddingBottom + safeBottom;
    return Math.max(1, Math.min(maximum, natural));
}

private bookshelfMoreSheetBodyHeight(): number {
    const rows = resolvePopupSpec('bookshelf-more-menu').actionHeight * 4;
    const usable = this.bookshelfMoreSheetHeight() - readerInteractiveSafeBottom(ReaderWindowCoordinator.metrics()) -
        MANGA_SHEET.handleZone - MANGA_SHEET.closeSize - MANGA_SHEET.quickHeaderPaddingBottom - MANGA_SHEET.quickPaddingBottom;
    return Math.max(1, Math.min(rows, usable));
}

private bookshelfMoreActions(): ReaderMenuActionView[] {
    return [
        new ReaderMenuActionView('batch', '批量管理', true),
        new ReaderMenuActionView('import', '本地导入', true),
        new ReaderMenuActionView('update', this.updateRunning ? `检查中 ${this.updateProgressDone}/${this.updateProgressTotal}` : this.backgroundUpdateRunning ? '正在自动检查' : '检查更新', this.canCheckUpdates && !this.updateRunning && !this.backgroundUpdateRunning),
        new ReaderMenuActionView('settings', '书架设置', true),
    ];
}

private bookshelfMoreAction(selectionId: string, id: string): void {
    if (id === 'update')
        this.moreIntentAction(selectionId, (): void => this.requestCheckUpdates())();
    else if (id === 'batch')
        this.moreIntentAction(selectionId, (): void => {
            this.dismissMoreMenu();
            this.onBatchManageRequested();
        })();
    else if (id === 'import')
        this.moreIntentAction(selectionId, (): void => {
            this.dismissMoreMenu();
            this.onImportRequested();
        })();
    else if (id === 'settings')
        this.moreIntentAction(selectionId, (): void => {
            this.dismissMoreMenu();
            this.onBookshelfSettingsRequested();
        })();
}

@Builder
private bookshelfMoreSheet(selectionId: string) {
    .width<
    >('100%').height<
    >(this.bookshelfMoreSheetHeight()).padding<
    >({ bottom: readerInteractiveSafeBottom(ReaderWindowCoordinator.metrics()) + MANGA_SHEET.quickPaddingBottom })
        .backgroundColor<
    >(mangaDirectoryColor('surface', this.appThemeScheme))
        .shadow<
    >({ radius: 48, color: this.appThemeScheme === 'night' ? '#66000000' : '#33000000', offsetX: 0, offsetY: -16 })
        .borderRadius<
    >({ topLeft: MANGA_SHEET.quickSheetRadius, topRight: MANGA_SHEET.quickSheetRadius, bottomLeft: 0, bottomRight: 0 });
}

private requestCheckUpdates(): void {
    if (!this.canCheckUpdates || this.updateRunning || this.backgroundUpdateRunning)
        return;
    this.dismissMoreMenu();
    this.onCheckUpdatesRequested();
}
